head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[image > M > getSrc]<br/>Image 컴포넌트에 표시되고 있는 이미지의 실제 요청 경로를 반환합니다.",
    "validation" : [
        "Image 컴포넌트에 표시되고 있는 이미지의 실제 URL 을 문자열로 반환합니다.",
        "src 속성값에 기준 경로가 보정된 이미지 경로가 반환됩니다.",
        "src 속성을 설정하지 않고 바인딩된 데이터도 없는 경우 현재 XML 페이지의 URL 경로가 반환됩니다.",
        "Image 컴포넌트에 현재 표시되는 이미지 경로를 반환하므로 setSrc() 메소드나 데이터 바인딩으로 이미지가 변경되면 변경된 이미지의 URL 이 반환됩니다.",
        "반환값에는 캐시 처리를 위한 쿼리스트링이 추가될 수 있습니다.",
        "이미지가 Data URL 형식으로 설정된 경우 반환값의 길이가 매우 길어질 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // 정적 select1 초기값 설정 (src : 절대경로 PNG / ref : 미설정)
    con_src.setValue("/img/png.png");
    con_ref.setValue("");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// Target 재생성 (body_sample.xml wframe 대신 정적 배치 구조를 직접 사용하므로 재생성 핸들러도 본 화면에서 제공한다)
scwin.btn_createTarget_onclick = function (e) {
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (scwin.target1) {
        scwin.target1.remove();
        scwin.target1 = null;
    }

    let cSrc = con_src.getValue();
    let cRef = con_ref.getValue();

    // ref 바인딩 시 이미지가 바로 표시되도록 행 0 을 선택한 상태로 시작한다
    dlt_image.setRowPosition(0);

    let lblSrc = (cSrc === '') ? '미설정' : scwin.shortUrl(cSrc);
    let lblRef = (cRef === '') ? '미설정' : cRef;

    $c.gcm.createLabel('label="[현재] target1 : src = ' + lblSrc + ' / ref = ' + lblRef + '\n[절차] con 값 변경 -> Target 재생성 -> getSrc 반환값 확인 버튼 클릭\n[확인] target2 는 src 와 ref 를 모두 설정하지 않은 정적 선언 Image 이며 재생성 대상이 아닙니다\n[참고] 바인딩 DataList 행 데이터 : 0 = /img/png.png, 1 = /img/jpg.jpg, 2 = /img/gif.gif / 프로토콜 포함 경로는 외부망 미연결 시 표시에 실패할 수 있습니다"', '', 'label1');

    // 조건 설정
    let properties = {
        ref : cRef,
    };

    let cList = $c.gcm.createCList(properties);

    // src 를 con 값으로 가변해야 하므로 공통 함수($c.gcm.createBasicImage 는 src 고정) 대신 직접 생성한다
    let grp_comp = $c.gcm.getTestGroup('');

    let strSrc = (cSrc === '') ? '' : ' src="' + cSrc + '"';

    let strTarget = '<xf:image ' + $c.gcm.strNameSpace + ' ' + cList + strSrc + ' style="width:200px; height:100px;"></xf:image>';

    scwin.target1 = await $p.dynamicCreate("target1", "image", strTarget, grp_comp);

    // 이미지 로드 성공 / 실패가 확정된 후에 표시 상태를 관측할 수 있으므로 대기한다
    await scwin.waitImage();
}



// 이미지 로드(성공/실패) 확정 대기
scwin.waitImage = function () {
    return new Promise(function (resolve) {
        let img = scwin.target1.render;

        if (img.complete) {
            resolve();
            return;
        }

        img.addEventListener("load", resolve, { once : true });
        img.addEventListener("error", resolve, { once : true });
        setTimeout(resolve, 2000);
    });
}



// 긴 URL(Data URL 등) 축약
scwin.shortUrl = function (url) {
    return (url.length > 60) ? url.substring(0, 60) + " ...(전체 길이 " + url.length + ")" : url;
}



// 이미지 표시 여부 판정 (src 문자열이 아니라 로드 성공 여부로 판정, 크기는 getBox 로 병행 확인)
scwin.isShown = function () {
    let img = scwin.target1.render;
    return img.complete && img.naturalWidth > 0;
}



// 이미지 실측 크기 (원본 / 렌더 박스)
scwin.getBox = function () {
    let img = scwin.target1.render;

    return "원본 " + img.naturalWidth + "x" + img.naturalHeight + ", 렌더 " + img.offsetWidth + "x" + img.offsetHeight;
}



// 바인딩된 DataList 의 현재 데이터값
scwin.getBindValue = function () {
    let pos = dlt_image.getRowPosition();

    return (pos < 0) ? "행 미선택" : dlt_image.getCellData(pos, "imgPath");
}



// 화면에 요청되는 기준 경로 (ref 바인딩 시 바인딩 데이터값, 아니면 src 설정값)
scwin.getBaseUrl = function () {
    return (con_ref.getValue() !== '') ? scwin.getBindValue() : con_src.getValue();
}



// validation 1, 2, 3, 5, 6 판정 출력
scwin.btn_getSrc_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    let img = scwin.target1.render;

    let base = scwin.getBaseUrl();
    let ret = scwin.target1.getSrc();
    let attr = img.getAttribute("src");

    let strBase = (base === '') ? "미설정" : scwin.shortUrl(base);
    let strAttr = (attr === null) ? "속성 없음" : (attr === '') ? "빈 문자열" : scwin.shortUrl(attr);
    let strRet = (ret === '') ? "빈 문자열" : scwin.shortUrl(ret);

    // 미설정 상태에서는 비교 대상 경로가 없으므로 보정 결과 판정을 생략한다
    let strSame = (base === '') ? "" : " / 설정값과 동일 : " + (base === ret);

    // [1,2] 반환 문자열 / 기준 경로 보정 결과
    bottom.setReturnValue("[1,2] 설정 경로 : " + strBase + " -> img src 속성 : " + strAttr + " -> getSrc() : " + strRet + strSame + " / 표시 : " + scwin.isShown() + " (" + scwin.getBox() + ")");

    // [3] src, ref 를 모두 설정하지 않은 정적 선언 Image (target2)
    let ret2 = target2.getSrc();

    bottom.setReturnValue("[3] target2 (src, ref 미설정) getSrc() : " + ret2 + " / 현재 XML 페이지 URL 일치 : " + (ret2 === document.location.href));

    // [5] 반환값에 추가된 캐시 처리용 쿼리스트링
    if (ret !== '') {
        let idx = ret.indexOf("?");

        bottom.setReturnValue("[5] getSrc() 반환값의 쿼리스트링 : " + ((idx < 0) ? "없음" : ret.substring(idx)));
    }

    // [6] Data URL 형식일 때의 반환값 길이
    if (base.indexOf("data:") === 0) {
        bottom.setReturnValue("[6] Data URL 반환값 길이 : " + ret.length + " / 앞 60자 : " + ret.substring(0, 60));
    }
};



// validation 4 판정 출력 (setSrc 메소드로 이미지 변경)
scwin.btn_setSrc_onclick = async function (e) {
    let bottom = wf_body_bottom.getObj("scwin");

    let before = scwin.target1.getSrc();

    scwin.target1.setSrc("/img/gif.gif");

    await scwin.waitImage();

    bottom.setReturnValue("[4] setSrc 호출 : " + scwin.shortUrl(before) + " -> getSrc() : " + scwin.shortUrl(scwin.target1.getSrc()) + " / 표시 : " + scwin.isShown() + " (" + scwin.getBox() + ")");
};



// validation 4 판정 출력 (데이터 바인딩 선택 변경으로 이미지 변경)
scwin.btn_selectRow_onclick = async function (e) {
    let bottom = wf_body_bottom.getObj("scwin");

    let before = scwin.target1.getSrc();

    dlt_image.setRowPosition(1);

    await scwin.waitImage();

    bottom.setReturnValue("[4] DataList 선택 행 1 (바인딩 데이터값 " + scwin.getBindValue() + ") : " + scwin.shortUrl(before) + " -> getSrc() : " + scwin.shortUrl(scwin.target1.getSrc()) + " / 표시 : " + scwin.isShown() + " (" + scwin.getBox() + ")");
};
